from pathlib import Path
import json,html
base=Path(__file__).resolve().parents[1]
places=json.loads((base/'places_16.json').read_text())
mini=[{k:p.get(k) for k in ('id','ko','de','address','lat','lon','source')} for p in places]
page=r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>ViennaNow | 명소 좌표 검토</title><style>
:root{--navy:#17374a;--line:#e2e8e5;--bg:#f8f6f2;--muted:#6c7b80}*{box-sizing:border-box}body{font:15px/1.55 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:var(--navy);background:var(--bg);margin:0}main{max-width:850px;padding:22px 16px 80px;margin:auto}.head{display:flex;justify-content:space-between;align-items:center}h1{font-size:26px;line-height:1.15;margin:22px 0 8px}.sub{color:var(--muted)}.card{border-radius:15px;padding:16px;background:white;border:1px solid var(--line);margin-top:12px}.row{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.field{margin-top:10px}.field span{display:block;font-size:12px;color:var(--muted);margin-bottom:4px}input,textarea{font:inherit;width:100%;padding:10px 11px;min-width:0;border-radius:8px;border:1px solid var(--line);background:#fafcfb}.cols{display:grid;grid-template-columns:1fr 1fr;gap:10px}a{color:#246e74}button{background:#17374a;color:white;border:0;padding:11px 15px;border-radius:10px;font:600 14px -apple-system,sans-serif;cursor:pointer;min-height:44px}.secondary{background:#e4ece9;color:var(--navy)}.badge{font-size:12px;background:#edf2f0;padding:5px 10px;border-radius:12px}.ok{background:#e2f3e9;color:#136a49}.warn{background:#ffefd8;color:#8a6215}.action{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}.hint{font-size:12px;color:var(--muted)}.warning{background:#fff3e8;border:1px solid #f1decd;padding:12px;border-radius:9px}button:focus-visible,input:focus-visible{outline:3px solid #d86d47;outline-offset:2px}@media(max-width:480px){.cols{grid-template-columns:1fr}}
</style></head><body><main><div class="head"><strong>ViennaNow <span class="badge">QA · Phase 10</span></strong><a href="/">앱으로 돌아가기</a></div><h1>대표 명소 16곳 위치 검토</h1><p class="sub">현재 앱 좌표는 기획용 근사값입니다. 실제 관광객 안내에는 출입구 또는 접근 가능한 장소 기준으로 공식 지도와 대조해야 합니다.</p><div class="warning"><b>검증 원칙</b><div>시설의 중심 좌표와 출입구 좌표는 다를 수 있습니다. 좌표, 출처 URL, 수동 확인 체크가 모두 있어야 '검토 완료'로 내보낼 수 있습니다. 자동으로 '검증 완료' 처리하지 않습니다.</div></div><div class="card row"><div><b id="progress">검토 완료 0 / 16곳</b><div class="hint">변경 내용은 현재 브라우저에만 임시 저장됩니다.</div></div><button id="export">검토 CSV 저장</button></div><section id="list"></section></main><script>
const PLACES=__DATA__;
const key='viennanow-phase10-location-review';
let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
const list=document.querySelector('#list');
const area=(id)=>document.getElementById('place-'+id);
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function valid(p,entry){const lat=Number(entry.lat),lon=Number(entry.lon);return String(entry.lat||'').trim()!==''&&String(entry.lon||'').trim()!==''&&lat>=48.10&&lat<=48.35&&lon>=16.15&&lon<=16.65&&/^https:\/\//i.test(entry.evidence||'')&&!!entry.approved;}
function render(){list.innerHTML=PLACES.map(p=>{let v=saved[p.id]||{};let ok=valid(p,v);return `<article class="card" id="place-${esc(p.id)}"><div class="row"><div><b>${esc(p.id)} · ${esc(p.ko)}</b><div class="sub">${esc(p.de)} · ${esc(p.address)}</div></div><span class="badge ${ok?'ok':'warn'}" data-review>${ok?'검토 완료':'수동 확인 필요'}</span></div><p class="hint">현재 앱의 근사 좌표: ${p.lat}, ${p.lon} · <a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">공식 장소 페이지</a> · <a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.de+', '+p.address)}">지도 검색</a></p><div class="cols"><label class="field"><span>검토한 출입구 위도 (lat)</span><input data-field="lat" data-id="${esc(p.id)}" inputmode="decimal" placeholder="예: 48.2085" value="${esc(v.lat??'')}"></label><label class="field"><span>검토한 출입구 경도 (lon)</span><input data-field="lon" data-id="${esc(p.id)}" inputmode="decimal" placeholder="예: 16.3731" value="${esc(v.lon??'')}"></label></div><label class="field"><span>검토 근거 URL (HTTPS 필수)</span><input data-field="evidence" data-id="${esc(p.id)}" type="url" placeholder="https://…" value="${esc(v.evidence??'')}"></label><label class="field"><span>특이사항 (출입구 방향, 보행 진입 조건 등)</span><input data-field="note" data-id="${esc(p.id)}" value="${esc(v.note??'')}"></label><label class="field"><input type="checkbox" data-field="approved" data-id="${esc(p.id)}" ${v.approved?'checked':''} style="width:auto;margin-right:7px">공식 지도로 위치 및 실제 출입구를 사람이 확인함</label></article>`}).join('');progress()}
function progress(){let n=PLACES.filter(p=>valid(p,saved[p.id]||{})).length;document.querySelector('#progress').textContent=`검토 완료 ${n} / ${PLACES.length}곳`;for(const p of PLACES){const tag=area(p.id)?.querySelector('[data-review]');if(!tag)continue;let ok=valid(p,saved[p.id]||{});tag.textContent=ok?'검토 완료':'수동 확인 필요';tag.className='badge '+(ok?'ok':'warn')}}
list.addEventListener('change',e=>update(e));list.addEventListener('input',e=>{if(e.target.type==='checkbox')return;update(e)});
function update(e){const t=e.target,id=t.dataset.id,k=t.dataset.field;if(!id||!k)return;saved[id]??={};saved[id][k]=t.type==='checkbox'?t.checked:t.value;localStorage.setItem(key,JSON.stringify(saved));progress()}
function quote(x){return '"'+String(x??'').replaceAll('"','""')+'"'}
document.querySelector('#export').addEventListener('click',()=>{const headers=['place_id','name_de','approx_lat','approx_lon','entrance_lat','entrance_lon','source_url','note','manual_review_status'];let rows=[headers];for(const p of PLACES){const v=saved[p.id]||{},ok=valid(p,v);rows.push([p.id,p.de,p.lat,p.lon,v.lat??'',v.lon??'',v.evidence??'',v.note??'',ok?'MANUALLY_REVIEWED':'PENDING']);}let csv='\ufeff'+rows.map(a=>a.map(quote).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='viennanow_coordinate_review.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
render();
</script></body></html>'''
page=page.replace('__DATA__',json.dumps(mini,ensure_ascii=False).replace('</','<\/'))
for target in [base/'coordinate_review.html',base/'public/coordinate_review.html']:
    target.write_text(page)
print('Created coordinate review for',len(mini),'venues')
